INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (1, 1, '', 'หน้าหลัก', '{SITE_NAME} ผู้ให้บริการออกแบบเว็บไซต์ ระบบองค์กร และโซลูชันดิจิทัลสำหรับธุรกิจทุกขนาด', '<h2>ยินดีต้อนรับสู่ {SITE_NAME}</h2><p>เราคือทีมนักออกแบบและนักพัฒนาที่เชื่อว่าเทคโนโลยีที่ดีต้อง<strong>ใช้งานง่าย คุ้มค่า และเติบโตไปพร้อมธุรกิจ</strong> ตลอดหลายปีที่ผ่านมาเราดูแลเว็บไซต์ ระบบงานภายใน และแอปพลิเคชันให้ลูกค้าทั้งภาคเอกชน ภาครัฐ และสถานศึกษา</p><ul><li><a href="{WEBURL}services">ออกแบบและพัฒนาเว็บไซต์</a> — เว็บไซต์องค์กร ร้านค้าออนไลน์ และเว็บไซต์หน่วยงาน รองรับทุกหน้าจอ</li><li><a href="{WEBURL}services">ระบบงานองค์กร</a> — ระบบเอกสาร ระบบจองห้องประชุม ระบบลงเวลา ปรับให้ตรงกับขั้นตอนงานจริง</li><li><a href="{WEBURL}portfolio">ผลงานที่ผ่านมา</a> — ตัวอย่างโครงการที่เราภูมิใจ</li><li><a href="{WEBURL}contact">ปรึกษาฟรี</a> — เล่าโจทย์ของท่าน แล้วเราจะเสนอแนวทางที่เหมาะสมที่สุด</li></ul><p><em>เนื้อหาทั้งหมดในเว็บไซต์นี้เป็นข้อมูลตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล › หน้าเพจ</em></p>', 'ออกแบบเว็บไซต์,ระบบองค์กร,โซลูชันดิจิทัล,{SITE_NAME}');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (2, 2, '', 'ข่าวสารและกิจกรรม', 'ข่าวสาร ประกาศ ผลิตภัณฑ์ใหม่ และกิจกรรมของ{SITE_NAME}', '<p>ติดตามความเคลื่อนไหว บริการใหม่ และกิจกรรมเพื่อสังคมของเราได้ที่นี่</p>', 'ข่าวสาร,ประชาสัมพันธ์,กิจกรรม,CSR');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (3, 3, '', 'บทความและความรู้', 'บทความความรู้ด้านเว็บไซต์ การตลาดออนไลน์ และคู่มือการใช้งานระบบจากทีมงาน{SITE_NAME}', '<p>รวมบทความความรู้ที่ทีมงานเขียนจากประสบการณ์จริง อ่านง่าย นำไปใช้ได้ทันที</p>', 'บทความ,ความรู้,SEO,การตลาดออนไลน์,คู่มือ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (4, 4, '', 'ผลงานของเรา', 'ตัวอย่างโครงการเว็บไซต์ ระบบงาน และแอปพลิเคชันที่{SITE_NAME}ออกแบบและพัฒนา', '<p>ผลงานบางส่วนที่เราภูมิใจ (ชื่อลูกค้าและรายละเอียดเป็นข้อมูลตัวอย่าง)</p>', 'ผลงาน,เว็บไซต์,แอปพลิเคชัน,ระบบงาน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (5, 5, '', 'แกลเลอรี่', 'ประมวลภาพกิจกรรม งานสัมมนา และบรรยากาศการทำงานของ{SITE_NAME}', '', 'แกลเลอรี่,ภาพกิจกรรม,อัลบั้ม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (6, 6, '', 'ดาวน์โหลดเอกสาร', 'โบรชัวร์ อัตราค่าบริการ แบบฟอร์ม และคู่มือการใช้งานของ{SITE_NAME}', '', 'ดาวน์โหลด,เอกสาร,แบบฟอร์ม,คู่มือ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (7, 7, '', 'วิดีโอ', 'วิดีโอแนะนำบริษัท บันทึกงานสัมมนา และสาธิตการใช้งานระบบ', '', 'วิดีโอ,YouTube');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (8, 8, '', 'ปฏิทินกิจกรรม', 'กำหนดการสัมมนา อบรม และกิจกรรมของ{SITE_NAME}', '', 'ปฏิทิน,กิจกรรม,สัมมนา,อบรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (9, 9, '', 'เว็บบอร์ด', 'ถาม-ตอบ แลกเปลี่ยนความรู้ และแจ้งปัญหาการใช้งานกับทีมงาน{SITE_NAME}', '', 'เว็บบอร์ด,ถาม-ตอบ,ช่วยเหลือ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (10, 10, '', 'เกี่ยวกับเรา', 'ประวัติ วิสัยทัศน์ และค่านิยมของ{SITE_NAME}', '<h2>เรื่องราวของเรา</h2><p>{SITE_NAME} เริ่มต้นจากทีมนักพัฒนาเล็ก ๆ ที่อยากให้ธุรกิจไทยทุกขนาดเข้าถึงเทคโนโลยีที่ดีได้ในราคาที่เหมาะสม วันนี้เรามีทีมงานกว่า 30 คน ดูแลเว็บไซต์และระบบงานให้ลูกค้ากว่า 300 องค์กร</p><h2>วิสัยทัศน์</h2><blockquote>เป็นพันธมิตรด้านดิจิทัลที่ลูกค้าไว้วางใจที่สุด ด้วยเทคโนโลยีที่ใช้งานง่ายและบริการที่จริงใจ</blockquote><h2>ค่านิยมของเรา</h2><ul><li><strong>เข้าใจลูกค้า</strong> — ฟังโจทย์จริงก่อนเสนอเทคโนโลยี</li><li><strong>เรียบง่าย</strong> — ระบบที่ดีต้องใช้ได้โดยไม่ต้องเปิดคู่มือ</li><li><strong>รับผิดชอบ</strong> — ดูแลต่อเนื่องหลังส่งมอบ</li><li><strong>เรียนรู้ตลอดเวลา</strong> — ทีมงานอบรมเทคโนโลยีใหม่ทุกสัปดาห์</li></ul><h2>ตัวเลขที่เราภูมิใจ</h2><table><tbody><tr><th>ลูกค้าที่ดูแล</th><td>300+ องค์กร</td></tr><tr><th>โครงการที่ส่งมอบ</th><td>850+ โครงการ</td></tr><tr><th>ความพึงพอใจเฉลี่ย</th><td>4.8 / 5</td></tr><tr><th>เวลาตอบกลับเฉลี่ย</th><td>ภายใน 2 ชั่วโมง</td></tr></tbody></table><p>ดูบริการทั้งหมดได้ที่ <a href="{WEBURL}services">บริการของเรา</a> หรือ <a href="{WEBURL}portfolio">ผลงานที่ผ่านมา</a></p>', 'เกี่ยวกับเรา,ประวัติบริษัท,วิสัยทัศน์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (11, 11, '', 'บริการของเรา', 'บริการออกแบบเว็บไซต์ ระบบงานองค์กร คลาวด์โฮสติ้ง และดูแลระบบรายปี', '<h2>บริการของเรา</h2><p>ครบทุกขั้นตอนตั้งแต่วางแผน ออกแบบ พัฒนา ไปจนถึงดูแลหลังส่งมอบ</p><h3>1. ออกแบบและพัฒนาเว็บไซต์</h3><p>เว็บไซต์องค์กร เว็บไซต์หน่วยงาน และร้านค้าออนไลน์ รองรับทุกหน้าจอ ผู้ดูแลอัปเดตเนื้อหาได้เอง</p><h3>2. ระบบงานองค์กร</h3><p>ระบบจัดการเอกสาร จองห้องประชุม ลงเวลาทำงาน แจ้งซ่อม ออกแบบตามขั้นตอนงานจริงของลูกค้า</p><h3>3. คลาวด์โฮสติ้งและอีเมลองค์กร</h3><p>เซิร์ฟเวอร์ประสิทธิภาพสูง สำรองข้อมูลทุกวัน พร้อมใบรับรอง SSL</p><h3>4. ดูแลระบบรายปี</h3><p>อัปเดตความปลอดภัย แก้ไขปัญหา และปรับปรุงเนื้อหาตามที่ร้องขอ</p><h2>ขั้นตอนการทำงาน</h2><ol><li>พูดคุยและสรุปความต้องการ</li><li>เสนอแนวทางและใบเสนอราคา</li><li>ออกแบบหน้าตาให้ลูกค้าอนุมัติ</li><li>พัฒนาและทดสอบ</li><li>อบรมการใช้งานและส่งมอบ</li><li>ดูแลต่อเนื่อง</li></ol><p>ดูอัตราค่าบริการตัวอย่างได้ที่ <a href="{WEBURL}download">ดาวน์โหลด</a> หรือ <a href="{WEBURL}contact">ติดต่อฝ่ายขาย</a></p>', 'บริการ,ออกแบบเว็บไซต์,ระบบงานองค์กร,โฮสติ้ง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (12, 12, '', 'ติดต่อเรา', 'ที่อยู่ เบอร์โทรศัพท์ อีเมล และเวลาทำการของ{SITE_NAME}', '<h2>ติดต่อ {SITE_NAME}</h2><p><strong>ที่อยู่ :</strong> เลขที่ 99/9 อาคารตัวอย่าง ชั้น 9 ถนนตัวอย่าง แขวงตัวอย่าง เขตตัวอย่าง กรุงเทพมหานคร 10000<br><strong>โทรศัพท์ :</strong> 02-000-0000<br><strong>ฝ่ายขาย :</strong> 08-0000-0000<br><strong>อีเมล :</strong> {SITE_EMAIL}<br><strong>เวลาทำการ :</strong> จันทร์ – ศุกร์ 08.30 – 17.30 น.</p><h3>สอบถามทางออนไลน์</h3><p>ฝากคำถามได้ที่ <a href="{WEBURL}forum">เว็บบอร์ด</a> ทีมงานตอบภายในวันทำการ หรือส่งอีเมลถึงฝ่ายขายได้ตลอดเวลา</p><p><em>ข้อมูลติดต่อเป็นตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล › หน้าเพจ › ติดต่อเรา</em></p>', 'ติดต่อเรา,ที่อยู่,โทรศัพท์,อีเมล');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (13, 2, '', 'เปิดตัวบริการคลาวด์โฮสติ้งรุ่นใหม่สำหรับเว็บไซต์องค์กร', 'บริการโฮสติ้งบนคลาวด์ที่ขยายทรัพยากรได้ทันที สำรองข้อมูลอัตโนมัติทุกวัน และมีทีมดูแลตลอด 24 ชั่วโมง', '<p>{SITE_NAME} เปิดตัว <strong>Cloud Hosting รุ่นใหม่</strong> ที่ออกแบบมาสำหรับเว็บไซต์องค์กรที่ต้องการความเสถียรและความปลอดภัยสูง ระบบสามารถขยายหน่วยประมวลผลและหน่วยความจำได้ทันทีเมื่อมีผู้เข้าชมมากขึ้น โดยไม่ต้องย้ายเซิร์ฟเวอร์</p><h3>จุดเด่นของบริการ</h3><ul><li>สำรองข้อมูลอัตโนมัติทุกวัน เก็บย้อนหลัง 14 วัน</li><li>ใบรับรอง SSL ฟรีตลอดอายุการใช้งาน</li><li>ระบบป้องกันการโจมตีแบบ DDoS เบื้องต้น</li><li>ทีมดูแลระบบตลอด 24 ชั่วโมง</li></ul><p>ลูกค้าเดิมที่ต้องการย้ายมาใช้บริการใหม่ ทีมงานจะย้ายข้อมูลให้โดยไม่มีค่าใช้จ่าย สอบถามรายละเอียดได้ที่ <a href="{WEBURL}contact">ติดต่อเรา</a></p>', 'คลาวด์,เว็บโฮสติ้ง,บริการใหม่');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (14, 2, '', 'ขอเชิญร่วมสัมมนาออนไลน์ "เว็บไซต์องค์กรในยุค AI" ไม่มีค่าใช้จ่าย', 'สัมมนาออนไลน์ความยาว 90 นาที ว่าด้วยการนำ AI มาช่วยสร้างเนื้อหาและดูแลลูกค้าผ่านเว็บไซต์', '<p>ขอเชิญผู้บริหารและผู้ดูแลเว็บไซต์เข้าร่วมสัมมนาออนไลน์ <strong>"เว็บไซต์องค์กรในยุค AI"</strong> พบกับแนวทางการนำปัญญาประดิษฐ์มาช่วยเขียนบทความ ตอบคำถามลูกค้า และวิเคราะห์พฤติกรรมผู้เข้าชม</p><h3>หัวข้อสัมมนา</h3><ol><li>AI ช่วยอะไรเว็บไซต์องค์กรได้บ้าง และข้อควรระวัง</li><li>สาธิตผู้ช่วยตอบคำถามอัตโนมัติบนเว็บไซต์</li><li>การดูแลข้อมูลส่วนบุคคลตาม PDPA เมื่อใช้ AI</li><li>ถาม-ตอบกับทีมวิทยากร</li></ol><p>ดูวันและเวลาได้ที่ <a href="{WEBURL}event">ปฏิทินกิจกรรม</a> ลงทะเบียนได้ที่หน้า <a href="{WEBURL}contact">ติดต่อเรา</a></p>', 'สัมมนา,AI,เว็บไซต์องค์กร');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (15, 2, '', 'ทีมพัฒนาคว้ารางวัลชนะเลิศการประกวดนวัตกรรมซอฟต์แวร์ระดับภูมิภาค', 'ระบบติดตามงานซ่อมบำรุงที่ทีมพัฒนาออกแบบให้ลูกค้า ได้รับรางวัลชนะเลิศประเภทนวัตกรรมเพื่อองค์กร', '<p>ขอแสดงความยินดีกับทีมพัฒนาของ {SITE_NAME} ที่ได้รับ<strong>รางวัลชนะเลิศ</strong> การประกวดนวัตกรรมซอฟต์แวร์ระดับภูมิภาค ประเภทนวัตกรรมเพื่อองค์กร จากผลงาน "ระบบติดตามงานซ่อมบำรุงผ่านมือถือ" ที่ช่วยให้ลูกค้าลดเวลารอซ่อมลงได้กว่าครึ่ง</p><blockquote>รางวัลนี้เป็นของลูกค้าทุกท่านที่ให้โจทย์ท้าทายและร่วมทดสอบระบบกับเราตั้งแต่วันแรก</blockquote><p>ดูรายละเอียดผลงานได้ที่หน้า <a href="{WEBURL}portfolio">ผลงานของเรา</a></p>', 'รางวัล,นวัตกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (16, 2, '', 'ประกาศวันหยุดประจำปีและช่องทางติดต่อกรณีเร่งด่วน', 'สำนักงานปิดทำการตามวันหยุดประจำปี ลูกค้าที่มีเหตุเร่งด่วนติดต่อทีมดูแลระบบได้ตลอด 24 ชั่วโมง', '<p>{SITE_NAME} ขอแจ้งวันหยุดประจำปีของสำนักงาน โดยในช่วงวันหยุดทีมดูแลระบบยังคงเฝ้าระวังเซิร์ฟเวอร์ของลูกค้าตามปกติ</p><table><thead><tr><th>ช่องทาง</th><th>เวลาให้บริการ</th></tr></thead><tbody><tr><td>อีเมล {SITE_EMAIL}</td><td>ตอบกลับภายใน 4 ชั่วโมง</td></tr><tr><td>โทรศัพท์ฉุกเฉิน 08-0000-0000</td><td>ตลอด 24 ชั่วโมง</td></tr><tr><td><a href="{WEBURL}forum">เว็บบอร์ด</a></td><td>ตอบในวันทำการถัดไป</td></tr></tbody></table>', 'ประกาศ,วันหยุด');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (17, 2, '', 'พนักงานจิตอาสาร่วมปลูกป่าชายเลนกับชุมชนชายฝั่ง', 'พนักงานกว่า 40 คนร่วมปลูกกล้าไม้ป่าชายเลน 1,000 ต้น พร้อมเรียนรู้ระบบนิเวศชายฝั่งจากปราชญ์ชุมชน', '<p>พนักงานจิตอาสาของ {SITE_NAME} กว่า 40 คน ร่วมกับชุมชนชายฝั่งปลูกกล้าไม้ป่าชายเลนจำนวน <strong>1,000 ต้น</strong> เพื่อฟื้นฟูแหล่งอนุบาลสัตว์น้ำและช่วยลดการกัดเซาะชายฝั่ง</p><p>นอกจากการปลูกป่า ทีมงานยังได้ทำเว็บไซต์ประชาสัมพันธ์การท่องเที่ยวเชิงนิเวศให้ชุมชนโดยไม่มีค่าใช้จ่าย ชมภาพบรรยากาศได้ที่ <a href="{WEBURL}gallery">แกลเลอรี่</a></p>', 'CSR,สิ่งแวดล้อม,จิตอาสา');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (18, 2, '', 'อัปเดตระบบจัดการเนื้อหาให้ลูกค้าทุกรายโดยไม่มีค่าใช้จ่าย', 'ระบบจัดการเนื้อหารุ่นใหม่เร็วขึ้น ปลอดภัยขึ้น และมีเครื่องมือจัดหน้าแบบลากวางให้ใช้งานทันที', '<p>ลูกค้าที่ใช้บริการดูแลเว็บไซต์กับ {SITE_NAME} จะได้รับการอัปเดตระบบจัดการเนื้อหารุ่นใหม่โดยอัตโนมัติ ภายในสัปดาห์นี้</p><h3>สิ่งที่เปลี่ยนแปลง</h3><ul><li>หน้าเว็บโหลดเร็วขึ้นจากการปรับปรุงระบบแคช</li><li>เครื่องมือจัดหน้าแรกแบบลากวาง</li><li>รองรับรูปภาพ WebP อัตโนมัติ ไฟล์เล็กลงแต่คมชัดเท่าเดิม</li><li>เสริมความปลอดภัยของการเข้าระบบ</li></ul><p>ระหว่างการอัปเดตเว็บไซต์ยังเปิดใช้งานได้ตามปกติ หากพบปัญหาแจ้งได้ที่ <a href="{WEBURL}forum">เว็บบอร์ด</a></p>', 'อัปเดตระบบ,ความปลอดภัย,บริการใหม่');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (19, 2, '', 'ประมวลภาพงานสัมมนาลูกค้าประจำปี', 'ขอบคุณลูกค้ากว่า 200 ท่านที่มาร่วมงานสัมมนาประจำปี พร้อมแลกเปลี่ยนประสบการณ์การใช้ระบบดิจิทัลในองค์กร', '<p>งานสัมมนาลูกค้าประจำปีผ่านไปอย่างอบอุ่น มีลูกค้าและพันธมิตรร่วมงานกว่า <strong>200 ท่าน</strong> ภายในงานมีการบรรยายเรื่องแนวโน้มเทคโนโลยี กรณีศึกษาจากลูกค้าจริง และบูธให้คำปรึกษาแบบตัวต่อตัว</p><p>ท่านที่พลาดงาน ชมภาพบรรยากาศได้ที่ <a href="{WEBURL}gallery">แกลเลอรี่</a> และวิดีโอบันทึกการบรรยายที่ <a href="{WEBURL}video">วิดีโอ</a></p>', 'สัมมนา,ลูกค้าสัมพันธ์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (20, 2, '', 'เปิดรับสมัครนักศึกษาฝึกงานสายเทคโนโลยี', 'รับนักศึกษาฝึกงานตำแหน่งนักพัฒนาเว็บ นักออกแบบ UX/UI และผู้ทดสอบระบบ มีค่าตอบแทนระหว่างฝึกงาน', '<p>{SITE_NAME} เปิดรับนักศึกษาฝึกงานที่รักการเรียนรู้ มาร่วมพัฒนาโครงการจริงกับทีมงานมืออาชีพ</p><h3>ตำแหน่งที่เปิดรับ</h3><ul><li>นักพัฒนาเว็บ (PHP / JavaScript)</li><li>นักออกแบบ UX/UI</li><li>ผู้ทดสอบระบบ (QA)</li></ul><p>ดาวน์โหลดใบสมัครได้ที่ <a href="{WEBURL}download">ดาวน์โหลด</a> แล้วส่งมาที่ {SITE_EMAIL}</p>', 'ร่วมงานกับเรา,ฝึกงาน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (21, 2, '', 'โครงการสอนเขียนโปรแกรมให้เยาวชนในชุมชน', 'ทีมงานสอนเยาวชนสร้างเว็บไซต์และเกมง่าย ๆ ทุกวันเสาร์ ตลอดภาคเรียน ณ ห้องสมุดชุมชน', '<p>โครงการ "โค้ดดิ้งสำหรับน้อง" จัดขึ้นทุกวันเสาร์ ณ ห้องสมุดชุมชน โดยพนักงานจิตอาสาผลัดกันเป็นผู้สอน เยาวชนได้เรียนรู้พื้นฐานการคิดเชิงคำนวณ การสร้างเว็บไซต์ และเกมง่าย ๆ</p><p>ตลอดภาคเรียนที่ผ่านมามีผู้เรียนจบหลักสูตร 36 คน และมีผลงานเว็บไซต์แนะนำชุมชนที่น้อง ๆ สร้างเองกว่า 10 เว็บ</p>', 'CSR,การศึกษา,จิตอาสา');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (22, 2, '', 'เปิดสำนักงานสาขาใหม่ รองรับลูกค้าภาคเหนือ', 'สำนักงานสาขาใหม่พร้อมห้องประชุมและทีมที่ปรึกษา ให้บริการลูกค้าในภาคเหนือได้ใกล้ชิดยิ่งขึ้น', '<p>เพื่อดูแลลูกค้าในภาคเหนือให้ใกล้ชิดยิ่งขึ้น {SITE_NAME} เปิดสำนักงานสาขาใหม่ พร้อมห้องประชุมสำหรับลูกค้าและทีมที่ปรึกษาประจำสาขา</p><p>ลูกค้าสามารถนัดหมายเข้าพบเพื่อปรึกษาโครงการ หรือเข้ารับการอบรมการใช้งานระบบได้ทุกวันทำการ ดูข้อมูลติดต่อได้ที่ <a href="{WEBURL}contact">ติดต่อเรา</a></p>', 'สาขาใหม่,ประกาศ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (23, 2, '', 'โปรโมชันแพ็กเกจเว็บไซต์สำหรับธุรกิจ SME ลด 20%', 'แพ็กเกจเว็บไซต์พร้อมโดเมน โฮสติ้ง และอบรมการใช้งาน ในราคาพิเศษสำหรับธุรกิจขนาดกลางและขนาดย่อม', '<p>สำหรับธุรกิจที่อยากมีเว็บไซต์แต่ไม่รู้จะเริ่มอย่างไร แพ็กเกจ SME ของเรามีทุกอย่างที่ต้องใช้ในราคาพิเศษ</p><table><thead><tr><th>รายการ</th><th>รายละเอียด</th></tr></thead><tbody><tr><td>เว็บไซต์</td><td>สูงสุด 10 หน้า รองรับมือถือ</td></tr><tr><td>โดเมนและโฮสติ้ง</td><td>ฟรีปีแรก</td></tr><tr><td>อบรมการใช้งาน</td><td>2 ชั่วโมง</td></tr><tr><td>ราคาพิเศษ</td><td>ลด 20% เมื่อทำสัญญาภายในเดือนนี้</td></tr></tbody></table><p>ดูรายละเอียดบริการทั้งหมดได้ที่ <a href="{WEBURL}services">บริการของเรา</a></p>', 'โปรโมชัน,SME,เว็บไซต์องค์กร');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (24, 2, '', 'ร่วมออกบูธในงานแสดงเทคโนโลยีเพื่อธุรกิจ', 'พบกับทีมงานและร่วมทดลองใช้ระบบตัวอย่างได้ที่บูธของเราตลอดสามวันของงาน', '<p>{SITE_NAME} ร่วมออกบูธในงานแสดงเทคโนโลยีเพื่อธุรกิจ ผู้เข้าชมงานสามารถทดลองใช้ระบบจองห้องประชุม ระบบลงเวลา และระบบจัดการเอกสาร พร้อมรับคำปรึกษาจากทีมงานได้ที่บูธตลอดสามวันของงาน</p>', 'งานแสดงสินค้า,สัมมนา');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (25, 2, '', 'มอบคอมพิวเตอร์ให้โรงเรียนในพื้นที่ห่างไกล', 'มอบคอมพิวเตอร์ที่ปรับปรุงสภาพแล้ว 30 เครื่อง พร้อมติดตั้งโปรแกรมเพื่อการเรียนรู้ให้โรงเรียน 3 แห่ง', '<p>ทีมงานนำคอมพิวเตอร์ที่ปลดระวางจากสำนักงานมาปรับปรุงสภาพ ติดตั้งโปรแกรมเพื่อการเรียนรู้ และมอบให้โรงเรียนในพื้นที่ห่างไกล 3 แห่ง รวม <strong>30 เครื่อง</strong></p><p>พร้อมกันนี้ได้จัดอบรมครูผู้ดูแลห้องคอมพิวเตอร์ให้ดูแลเครื่องและติดตั้งโปรแกรมได้ด้วยตนเอง</p>', 'CSR,การศึกษา');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (26, 2, '', 'นโยบายคุ้มครองข้อมูลส่วนบุคคลของลูกค้า (PDPA)', 'สรุปแนวทางการเก็บ ใช้ และดูแลข้อมูลส่วนบุคคลของลูกค้าตามพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล', '<p>{SITE_NAME} ให้ความสำคัญกับข้อมูลส่วนบุคคลของลูกค้า และปฏิบัติตามพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคลอย่างเคร่งครัด</p><ol><li>เก็บข้อมูลเท่าที่จำเป็นต่อการให้บริการเท่านั้น</li><li>เข้ารหัสข้อมูลสำคัญทั้งระหว่างส่งและระหว่างจัดเก็บ</li><li>จำกัดสิทธิการเข้าถึงข้อมูลเฉพาะผู้ที่เกี่ยวข้อง</li><li>ลูกค้าขอดู แก้ไข หรือลบข้อมูลของตนเองได้ตลอดเวลา</li></ol><p>ติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคลได้ที่ {SITE_EMAIL}</p>', 'PDPA,ความปลอดภัย,ประกาศ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (27, 3, '', '7 ขั้นตอนเตรียมตัวก่อนทำเว็บไซต์องค์กร', 'เตรียมให้พร้อมก่อนคุยกับผู้พัฒนา ช่วยให้ได้เว็บไซต์ตรงใจ เสร็จเร็ว และไม่บานปลาย', '<p>เว็บไซต์ที่ดีเริ่มจากการเตรียมตัวที่ดี ลองไล่ตามรายการนี้ก่อนเริ่มโครงการ</p><ol><li><strong>ตั้งเป้าหมาย</strong> อยากได้ลูกค้าใหม่ ลดงานตอบคำถาม หรือสร้างความน่าเชื่อถือ</li><li><strong>รู้จักผู้ใช้</strong> ใครจะเข้ามา และเขาต้องการอะไร</li><li><strong>วางโครงสร้างเมนู</strong> ไม่เกิน 7 เมนูหลัก</li><li><strong>เตรียมเนื้อหา</strong> ข้อความ รูปภาพ และเอกสารที่ต้องใช้</li><li><strong>เลือกชื่อโดเมน</strong> สั้น จำง่าย สะกดไม่ผิด</li><li><strong>กำหนดผู้ดูแล</strong> ใครจะอัปเดตข่าวและตอบคำถาม</li><li><strong>ตั้งงบประมาณ</strong> รวมค่าดูแลรายปี ไม่ใช่แค่ค่าทำครั้งแรก</li></ol><p>ดาวน์โหลด <a href="{WEBURL}download">แบบฟอร์มสรุปความต้องการเว็บไซต์</a> ไปกรอกก่อนได้เลย</p>', 'เว็บไซต์องค์กร,วางแผน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (28, 3, '', 'เลือกชื่อโดเมนอย่างไรให้จำง่ายและปลอดภัย', 'หลักการตั้งชื่อโดเมนให้จำง่าย เลือกนามสกุลให้เหมาะ และป้องกันโดเมนหมดอายุ', '<p>ชื่อโดเมนคือที่อยู่ของธุรกิจบนอินเทอร์เน็ต ควรเลือกให้ดีตั้งแต่แรกเพราะเปลี่ยนภายหลังมีค่าใช้จ่ายสูง</p><h3>หลักการเลือก</h3><ul><li>สั้น ออกเสียงง่าย ไม่มีขีดกลางหลายตัว</li><li>นิติบุคคลในไทยพิจารณา .co.th เพิ่มความน่าเชื่อถือ</li><li>จดชื่อที่คล้ายกันไว้ด้วยเพื่อป้องกันการแอบอ้าง</li></ul><h3>ป้องกันโดเมนหมดอายุ</h3><p>ตั้งต่ออายุอัตโนมัติ และใช้อีเมลกลางขององค์กรเป็นอีเมลผู้ติดต่อ ไม่ใช้อีเมลส่วนตัวของพนักงาน</p>', 'โดเมน,ความปลอดภัย');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (29, 3, '', 'SEO เบื้องต้น ทำให้เว็บไซต์ถูกค้นพบบน Google', 'พื้นฐาน SEO ที่เจ้าของเว็บทำเองได้ ตั้งแต่ชื่อหน้า คำอธิบาย ไปจนถึงความเร็วของเว็บไซต์', '<p>SEO (Search Engine Optimization) คือการปรับเว็บไซต์ให้เครื่องมือค้นหาเข้าใจและแนะนำเว็บของเราให้ผู้ค้นหา</p><h3>สิ่งที่ทำได้ทันที</h3><ol><li>ตั้งชื่อหน้า (Title) ให้ตรงกับเนื้อหาและไม่ซ้ำกัน</li><li>เขียนคำอธิบาย (Description) ชวนคลิกไม่เกิน 150 ตัวอักษร</li><li>ใส่ข้อความแทนรูป (alt) ทุกรูป</li><li>เชื่อมโยงบทความที่เกี่ยวข้องกัน</li><li>ทำให้เว็บโหลดเร็ว โดยเฉพาะบนมือถือ</li></ol><p>ระบบของเราสร้าง Sitemap และข้อมูลโครงสร้าง (JSON-LD) ให้อัตโนมัติ เจ้าของเว็บจึงโฟกัสที่เนื้อหาได้เต็มที่</p>', 'SEO,Google,การตลาดออนไลน์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (30, 3, '', 'วัดผลการตลาดออนไลน์ด้วยตัวชี้วัดที่ใช่', 'ยอดไลก์ไม่ใช่ทุกอย่าง รู้จักตัวชี้วัดที่บอกผลลัพธ์ทางธุรกิจได้จริง', '<p>ตัวเลขบนแดชบอร์ดมีมากมาย แต่ไม่ใช่ทุกตัวที่บอกว่าการตลาดได้ผล</p><table><thead><tr><th>ตัวชี้วัด</th><th>บอกอะไร</th></tr></thead><tbody><tr><td>อัตราการเปลี่ยนเป็นลูกค้า</td><td>ผู้เข้าชมกี่เปอร์เซ็นต์ที่ติดต่อหรือซื้อ</td></tr><tr><td>ต้นทุนต่อลูกค้าใหม่</td><td>ใช้เงินเท่าไรจึงได้ลูกค้าหนึ่งราย</td></tr><tr><td>อัตราการกลับมาซ้ำ</td><td>ลูกค้าพอใจและกลับมาใช้บริการหรือไม่</td></tr></tbody></table><p>เลือกตัวชี้วัดหลักไม่เกิน 3 ตัว แล้วติดตามทุกเดือนอย่างสม่ำเสมอ</p>', 'การตลาดออนไลน์,วัดผล');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (31, 3, '', 'คู่มือเพิ่มบทความและรูปภาพในระบบหลังบ้าน', 'ขั้นตอนเขียนบทความ ใส่รูปประกอบ ติดแท็ก และตั้งเวลาเผยแพร่ สำหรับผู้ดูแลเว็บไซต์มือใหม่', '<ol><li>เข้าระบบแล้วเลือกเมนู <strong>เนื้อหา</strong> › โมดูลที่ต้องการ</li><li>กด <strong>เขียนบทความ</strong> กรอกหัวข้อและเนื้อหา</li><li>อัปโหลดรูปประกอบ ระบบย่อขนาดและแปลงเป็น WebP ให้อัตโนมัติ</li><li>เลือกหมวดหมู่และใส่แท็ก เพื่อให้ผู้อ่านค้นหาเจอง่าย</li><li>กำหนดวันที่เผยแพร่ แล้วกด <strong>บันทึก</strong></li></ol><p>ดาวน์โหลดคู่มือฉบับเต็มได้ที่ <a href="{WEBURL}download">ดาวน์โหลด</a></p>', 'คู่มือ,ระบบหลังบ้าน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (32, 3, '', 'วิธีสำรองข้อมูลเว็บไซต์ด้วยตัวเอง', 'สำรองฐานข้อมูลและไฟล์ของเว็บไซต์เก็บไว้เอง เผื่อกรณีฉุกเฉิน', '<p>แม้ระบบจะสำรองข้อมูลให้ทุกวัน แต่การมีสำเนาเก็บไว้เองเป็นหลักประกันที่ดีที่สุด</p><h3>สิ่งที่ต้องสำรอง</h3><ul><li>ฐานข้อมูล — ส่งออกจากเมนูผู้ดูแล › สำรองฐานข้อมูล</li><li>โฟลเดอร์ datas/ — รูปภาพและไฟล์ที่อัปโหลด</li><li>ไฟล์ settings/ — ค่ากำหนดของเว็บไซต์</li></ul><p>เก็บสำเนาไว้อย่างน้อยสองที่ และทดลองกู้คืนปีละครั้งเพื่อให้มั่นใจว่าใช้ได้จริง</p>', 'สำรองข้อมูล,คู่มือ,ความปลอดภัย');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (33, 3, '', 'HTTPS คืออะไร ทำไมทุกเว็บไซต์ต้องมี', 'รู้จัก HTTPS และใบรับรอง SSL ที่ช่วยปกป้องข้อมูลผู้ใช้และเพิ่มความน่าเชื่อถือ', '<p>HTTPS คือการเชื่อมต่อแบบเข้ารหัสระหว่างเบราว์เซอร์กับเว็บไซต์ ป้องกันไม่ให้ผู้อื่นดักอ่านข้อมูลระหว่างทาง</p><ul><li>เบราว์เซอร์จะเตือนผู้ใช้ทันทีถ้าเว็บไม่มี HTTPS</li><li>เครื่องมือค้นหาให้คะแนนเว็บที่ปลอดภัยดีกว่า</li><li>จำเป็นสำหรับฟอร์มติดต่อ การเข้าระบบ และการชำระเงิน</li></ul>', 'HTTPS,ความปลอดภัย');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (34, 3, '', 'เขียนคอนเทนต์ให้ทั้งคนอ่านและเครื่องมือค้นหาชอบ', 'เทคนิคเขียนบทความที่อ่านง่าย ตอบคำถามผู้อ่าน และถูกค้นพบได้ง่าย', '<p>คอนเทนต์ที่ดีเริ่มจากคำถามของผู้อ่าน ไม่ใช่สิ่งที่เราอยากขาย</p><ol><li>เปิดเรื่องด้วยคำตอบ แล้วค่อยขยายรายละเอียด</li><li>ใช้หัวข้อย่อยและรายการ ให้สแกนอ่านได้เร็ว</li><li>ใส่ตัวอย่างและตัวเลขจริง</li><li>ปิดท้ายด้วยสิ่งที่ผู้อ่านทำต่อได้ทันที</li></ol>', 'คอนเทนต์,SEO');
