INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (1, 8, 'ประชุมผู้ถือหุ้นประจำปี', '<p>ประชุมผู้ถือหุ้นประจำปี ณ ห้องประชุมใหญ่ ชั้น 9 เพื่อรายงานผลการดำเนินงานและพิจารณาแผนงานปีถัดไป</p>', 'ประชุมผู้ถือหุ้นประจำปี ณ ห้องประชุมใหญ่ ชั้น 9 เพื่อรายงานผลการดำเนินงานและพิจารณาแผนงานปีถัดไป', 'ประชุมผู้ถือหุ้นประจำปี', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 3 DAY) + INTERVAL 0 DAY + INTERVAL '12:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 3 DAY) + INTERVAL '09:00' HOUR_MINUTE, '#B91C1C', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (2, 8, 'อบรมการใช้งานระบบหลังบ้านสำหรับลูกค้าใหม่', '<p>อบรมเชิงปฏิบัติการสำหรับผู้ดูแลเว็บไซต์ของลูกค้าใหม่ เรียนรู้การเขียนข่าว จัดอัลบั้ม และจัดเมนู กรุณานำโน้ตบุ๊กมาด้วย</p>', 'อบรมเชิงปฏิบัติการสำหรับผู้ดูแลเว็บไซต์ของลูกค้าใหม่ เรียนรู้การเขียนข่าว จัดอัลบั้ม และจัดเมนู กรุณานำโน้ตบุ๊กมาด้วย', 'อบรมการใช้งานระบบหลังบ้านสำหรับลูกค้าใหม่', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 10 DAY) + INTERVAL 0 DAY + INTERVAL '16:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 10 DAY) + INTERVAL '13:30' HOUR_MINUTE, '#0E7490', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (3, 8, 'สัมมนาออนไลน์ เว็บไซต์องค์กรในยุค AI', '<p>สัมมนาออนไลน์ไม่มีค่าใช้จ่าย ลงทะเบียนแล้วรับลิงก์เข้าร่วมทางอีเมล ดูรายละเอียดใน<a href="{WEBURL}news">ข่าวสาร</a></p>', 'สัมมนาออนไลน์ไม่มีค่าใช้จ่าย ลงทะเบียนแล้วรับลิงก์เข้าร่วมทางอีเมล ดูรายละเอียดใน ข่าวสาร', 'สัมมนาออนไลน์ เว็บไซต์องค์กรในยุค AI', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 17 DAY) + INTERVAL 0 DAY + INTERVAL '20:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 17 DAY) + INTERVAL '19:00' HOUR_MINUTE, '#7C3AED', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (4, 8, 'จิตอาสาปลูกป่าชายเลน ครั้งที่ 2', '<p>กิจกรรมจิตอาสาสองวัน เดินทางพร้อมกันหน้าสำนักงานเวลา 07.30 น. มีที่พักและอาหารให้</p>', 'กิจกรรมจิตอาสาสองวัน เดินทางพร้อมกันหน้าสำนักงานเวลา 07.30 น. มีที่พักและอาหารให้', 'จิตอาสาปลูกป่าชายเลน ครั้งที่ 2', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 24 DAY) + INTERVAL 1 DAY + INTERVAL '15:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 24 DAY) + INTERVAL '07:30' HOUR_MINUTE, '#16A34A', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (5, 8, 'วันหยุดประจำปี สำนักงานปิดทำการ', '<p>สำนักงานปิดทำการ ทีมดูแลระบบยังให้บริการกรณีเร่งด่วนที่ 08-0000-0000</p>', 'สำนักงานปิดทำการ ทีมดูแลระบบยังให้บริการกรณีเร่งด่วนที่ 08-0000-0000', 'วันหยุดประจำปี สำนักงานปิดทำการ', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 1 DAY) + INTERVAL 0 DAY + INTERVAL '17:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 1 DAY) + INTERVAL '08:30' HOUR_MINUTE, '#6B7280', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (6, 8, 'Open House เปิดบ้านแนะนำบริการ', '<p>เยี่ยมชมสำนักงาน พบทีมงาน และทดลองใช้ระบบตัวอย่าง พร้อมรับคำปรึกษาแบบตัวต่อตัว</p>', 'เยี่ยมชมสำนักงาน พบทีมงาน และทดลองใช้ระบบตัวอย่าง พร้อมรับคำปรึกษาแบบตัวต่อตัว', 'Open House เปิดบ้านแนะนำบริการ', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 8 DAY) + INTERVAL 0 DAY + INTERVAL '15:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 8 DAY) + INTERVAL '10:00' HOUR_MINUTE, '#F59E0B', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (7, 8, 'งานแสดงเทคโนโลยีเพื่อธุรกิจ', '<p>พบกับบูธของเราตลอดสามวันของงาน ทดลองใช้ระบบจองห้องประชุม ระบบลงเวลา และระบบจัดการเอกสาร</p>', 'พบกับบูธของเราตลอดสามวันของงาน ทดลองใช้ระบบจองห้องประชุม ระบบลงเวลา และระบบจัดการเอกสาร', 'งานแสดงเทคโนโลยีเพื่อธุรกิจ', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 14 DAY) + INTERVAL 2 DAY + INTERVAL '18:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 14 DAY) + INTERVAL '10:00' HOUR_MINUTE, '#B91C1C', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (8, 8, 'Workshop SEO สำหรับเจ้าของธุรกิจ', '<p>เวิร์กช็อปหนึ่งวัน ปรับเว็บไซต์ของท่านให้ถูกค้นพบง่ายขึ้นด้วยตนเอง รับจำนวนจำกัด 20 ท่าน</p>', 'เวิร์กช็อปหนึ่งวัน ปรับเว็บไซต์ของท่านให้ถูกค้นพบง่ายขึ้นด้วยตนเอง รับจำนวนจำกัด 20 ท่าน', 'Workshop SEO สำหรับเจ้าของธุรกิจ', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 21 DAY) + INTERVAL 0 DAY + INTERVAL '16:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 21 DAY) + INTERVAL '09:00' HOUR_MINUTE, '#0E7490', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (9, 8, 'ประชุมสรุปความต้องการโครงการใหม่', '<p>ประชุมร่วมกับลูกค้าเพื่อสรุปขอบเขตงานและกำหนดการส่งมอบ</p>', 'ประชุมร่วมกับลูกค้าเพื่อสรุปขอบเขตงานและกำหนดการส่งมอบ', 'ประชุมสรุปความต้องการโครงการใหม่', 1, (CURDATE() + INTERVAL 2 DAY) + INTERVAL 0 DAY + INTERVAL '11:30' HOUR_MINUTE, (CURDATE() + INTERVAL 2 DAY) + INTERVAL '10:00' HOUR_MINUTE, '#1F2937', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (10, 8, 'สัมมนาออนไลน์ เริ่มต้นขายของออนไลน์', '<p>สำหรับผู้ประกอบการที่เพิ่งเริ่มขายออนไลน์ เลือกช่องทาง ตั้งราคา และจัดการคำสั่งซื้อ</p>', 'สำหรับผู้ประกอบการที่เพิ่งเริ่มขายออนไลน์ เลือกช่องทาง ตั้งราคา และจัดการคำสั่งซื้อ', 'สัมมนาออนไลน์ เริ่มต้นขายของออนไลน์', 1, (CURDATE() + INTERVAL 5 DAY) + INTERVAL 0 DAY + INTERVAL '15:30' HOUR_MINUTE, (CURDATE() + INTERVAL 5 DAY) + INTERVAL '14:00' HOUR_MINUTE, '#7C3AED', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (11, 8, 'อบรมความปลอดภัยไซเบอร์สำหรับพนักงาน', '<p>อบรมภายในเรื่องการตั้งรหัสผ่าน การสังเกตอีเมลหลอกลวง และการรายงานเหตุผิดปกติ</p>', 'อบรมภายในเรื่องการตั้งรหัสผ่าน การสังเกตอีเมลหลอกลวง และการรายงานเหตุผิดปกติ', 'อบรมความปลอดภัยไซเบอร์สำหรับพนักงาน', 1, (CURDATE() + INTERVAL 12 DAY) + INTERVAL 0 DAY + INTERVAL '12:00' HOUR_MINUTE, (CURDATE() + INTERVAL 12 DAY) + INTERVAL '09:30' HOUR_MINUTE, '#16A34A', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
