INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (1, 4, 'เว็บไซต์โรงแรมริมทะเล', 'เว็บไซต์,โรงแรม,จองห้องพัก', '<p>เว็บไซต์สองภาษาพร้อมระบบจองห้องพักออนไลน์ แสดงห้องว่างแบบทันที และเชื่อมต่อการชำระเงิน</p><ul><li>ออกแบบให้รูปห้องพักโดดเด่นบนมือถือ</li><li>ยอดจองผ่านเว็บเพิ่มขึ้น 35% ในสามเดือนแรก</li></ul>', UNIX_TIMESTAMP(NOW() - INTERVAL 10 DAY), '1.webp', 'https://www.example.com/', '1', 88);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (2, 4, 'ระบบจองห้องประชุมออนไลน์', 'ระบบงาน,จองห้องประชุม', '<p>ระบบจองห้องประชุมสำหรับองค์กรที่มีหลายอาคาร แสดงตารางว่างของทุกห้อง อนุมัติการจองผ่านมือถือ และแจ้งเตือนทางอีเมล</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 30 DAY), '2.webp', '', '1', 64);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (3, 4, 'แอปสะสมแต้มร้านกาแฟ', 'แอปพลิเคชัน,สะสมแต้ม,ร้านกาแฟ', '<p>แอปสะสมแต้มและแลกรางวัลสำหรับร้านกาแฟ 12 สาขา สแกนคิวอาร์โค้ดที่เคาน์เตอร์ได้ทันที พร้อมระบบส่งโปรโมชันถึงสมาชิก</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 50 DAY), '3.webp', '', '1', 120);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (4, 4, 'เว็บไซต์โรงเรียนอนุบาล', 'เว็บไซต์,โรงเรียน', '<p>เว็บไซต์โรงเรียนที่ครูอัปเดตข่าวและอัลบั้มภาพกิจกรรมได้เองจากมือถือ มีปฏิทินกิจกรรมและดาวน์โหลดแบบฟอร์มสำหรับผู้ปกครอง</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 70 DAY), '4.webp', '', '1', 51);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (5, 4, 'ระบบแจ้งซ่อมและบำรุงรักษา', 'ระบบงาน,แจ้งซ่อม,รางวัล', '<p>ผลงานที่ได้รับรางวัลชนะเลิศด้านนวัตกรรมเพื่อองค์กร พนักงานแจ้งซ่อมพร้อมรูปถ่าย ช่างรับงานและปิดงานผ่านมือถือ ผู้บริหารดูสถิติได้ทันที</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 90 DAY), '5.webp', '', '1', 143);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (6, 4, 'ร้านค้าออนไลน์ผลิตภัณฑ์ชุมชน', 'ร้านค้าออนไลน์,ชุมชน', '<p>ร้านค้าออนไลน์สำหรับวิสาหกิจชุมชน ขายผ้าทอมือและอาหารแปรรูป รองรับการชำระเงินผ่านคิวอาร์โค้ดและคำนวณค่าส่งอัตโนมัติ</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 110 DAY), '6.webp', '', '1', 97);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (7, 4, 'เว็บไซต์คลินิกทันตกรรม', 'เว็บไซต์,คลินิก,นัดหมาย', '<p>เว็บไซต์คลินิกพร้อมระบบนัดหมายล่วงหน้า แจ้งเตือนก่อนถึงวันนัด และบทความความรู้ด้านสุขภาพช่องปาก</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 130 DAY), '7.webp', '', '1', 72);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (8, 4, 'แอปติดตามพัสดุสำหรับร้านค้า', 'แอปพลิเคชัน,ขนส่ง', '<p>แอปรวมเลขพัสดุจากหลายบริษัทขนส่งไว้ในที่เดียว ร้านค้าส่งลิงก์ติดตามให้ลูกค้าได้อัตโนมัติ</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 150 DAY), '8.webp', '', '1', 58);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (9, 4, 'ระบบลงเวลาทำงานด้วยใบหน้าและตำแหน่ง', 'ระบบงาน,ลงเวลา,บุคคล', '<p>ระบบลงเวลาทำงานผ่านมือถือ ตรวจตำแหน่งที่ตั้ง คำนวณชั่วโมงทำงานและวันลา และส่งออกรายงานให้ฝ่ายบุคคลได้ทันที</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 170 DAY), '9.webp', '', '1', 110);
INSERT INTO `{prefix}_portfolio` (`id`, `module_id`, `title`, `keywords`, `detail`, `created_at`, `image`, `url`, `published`, `visited`) VALUES (10, 4, 'เว็บไซต์องค์การบริหารส่วนตำบล', 'เว็บไซต์,หน่วยงานรัฐ,ITA', '<p>เว็บไซต์หน่วยงานท้องถิ่นที่รองรับการเปิดเผยข้อมูลสาธารณะตามเกณฑ์ ITA มีระบบร้องเรียนออนไลน์และประกาศจัดซื้อจัดจ้าง</p>', UNIX_TIMESTAMP(NOW() - INTERVAL 190 DAY), '10.webp', '', '1', 45);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (1, 9, 1, 'ผู้ดูแล', 1, '', '', 410, 0, 0, '', 0, NULL, NULL, 1, 1, 1, 0, 'กติกาการใช้งานเว็บบอร์ด โปรดอ่านก่อนตั้งกระทู้', '<ol><li>ใช้ถ้อยคำสุภาพ ไม่พาดพิงบุคคลอื่น</li><li>ตั้งกระทู้ให้ตรงหมวดหมู่</li><li>ห้ามเผยแพร่ข้อมูลส่วนตัว เช่น รหัสผ่าน หรือเบอร์โทรศัพท์</li><li>ปัญหาเร่งด่วนโปรดติดต่อทีมซัพพอร์ตโดยตรง</li></ol>', NOW() - INTERVAL 60 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 60 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (2, 9, 1, 'คุณเอก', 1, '', '', 84, 2, 2, 'คุณเอก', 1, NOW() - INTERVAL 4 DAY - INTERVAL 2 HOUR, NULL, 1, 1, 0, 0, 'ทำเว็บไซต์องค์กรใช้เวลากี่วันครับ', '<p>สนใจทำเว็บไซต์บริษัทประมาณ 8 หน้า มีข่าวสารและแบบฟอร์มติดต่อ ปกติใช้เวลากี่วันครับ</p>', NOW() - INTERVAL 6 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 4 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (3, 9, 2, 'คุณมด', 1, '', '', 67, 2, 4, 'คุณมด', 1, NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR, NULL, 1, 1, 0, 0, 'ลืมรหัสผ่านเข้าระบบหลังบ้านต้องทำอย่างไร', '<p>ผู้ดูแลเว็บคนเก่าลาออกไปแล้ว และไม่มีใครจำรหัสผ่านได้ ต้องทำอย่างไรคะ</p>', NOW() - INTERVAL 4 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (4, 9, 2, 'คุณบี', 1, '', '', 52, 3, 7, 'ทีมซัพพอร์ต', 1, NOW() - INTERVAL 0 DAY - INTERVAL 3 HOUR, NULL, 1, 1, 0, 0, 'อัปโหลดรูปไม่ได้ ขึ้นว่าไฟล์ใหญ่เกินกำหนด', '<p>ถ่ายรูปจากมือถือแล้วอัปโหลดเข้าอัลบั้มไม่ได้ ขึ้นว่าไฟล์ใหญ่เกินครับ</p>', NOW() - INTERVAL 3 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 0 DAY - INTERVAL 3 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (5, 9, 3, 'คุณแนน', 1, '', '', 39, 1, 8, 'ทีมงาน', 1, NOW() - INTERVAL 8 DAY - INTERVAL 1 HOUR, NULL, 1, 1, 0, 0, 'อยากให้มีคู่มือการใช้งานแบบวิดีโอ', '<p>คู่มือ PDF ละเอียดดีค่ะ แต่ถ้ามีวิดีโอสั้น ๆ ประกอบจะเข้าใจง่ายขึ้นมาก</p>', NOW() - INTERVAL 9 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 8 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (6, 9, 1, 'คุณก้อง', 1, '', '', 71, 2, 10, 'คุณก้อง', 1, NOW() - INTERVAL 11 DAY - INTERVAL 2 HOUR, NULL, 1, 1, 0, 0, 'ร้านค้าออนไลน์รองรับการชำระเงินผ่านคิวอาร์โค้ดไหม', '<p>ถ้าทำร้านค้าออนไลน์ ลูกค้าสแกนจ่ายผ่านคิวอาร์โค้ดได้ไหมครับ</p>', NOW() - INTERVAL 13 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 11 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (7, 9, 2, 'คุณโอ๊ต', 1, '', '', 45, 1, 11, 'ทีมซัพพอร์ต', 1, NOW() - INTERVAL 17 DAY - INTERVAL 1 HOUR, NULL, 1, 1, 0, 0, 'ย้ายเว็บไซต์จากผู้ให้บริการเดิมมาได้หรือไม่', '<p>เว็บไซต์เดิมทำด้วยระบบอื่น ย้ายข้อมูลข่าวเก่ามาได้ไหมครับ</p>', NOW() - INTERVAL 18 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 17 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (8, 9, 3, 'คุณจอย', 1, '', '', 28, 1, 12, 'ทีมซัพพอร์ต', 1, NOW() - INTERVAL 1 DAY - INTERVAL 1 HOUR, NULL, 1, 1, 0, 0, 'ขอบคุณทีมซัพพอร์ตที่ช่วยแก้ปัญหาอย่างรวดเร็ว', '<p>เว็บล่มตอนดึก แจ้งไปไม่ถึงชั่วโมงก็กลับมาใช้ได้ ขอบคุณมากค่ะ</p>', NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 1 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (1, 9, 2, '<p>โดยทั่วไปประมาณ 3-4 สัปดาห์ครับ ขึ้นกับความพร้อมของเนื้อหา ถ้าเตรียมข้อความและรูปไว้ครบจะเร็วขึ้นมากครับ</p>', 'ฝ่ายขาย', 1, '', '', NULL, NOW() - INTERVAL 5 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (2, 9, 2, '<p>ขอบคุณครับ เดี๋ยวดาวน์โหลดแบบฟอร์มสรุปความต้องการไปกรอกก่อนครับ</p>', 'คุณเอก', 1, '', '', NULL, NOW() - INTERVAL 4 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (3, 9, 3, '<p>กดลิงก์ "ลืมรหัสผ่าน" ที่หน้าเข้าระบบ ระบบจะส่งลิงก์ตั้งรหัสใหม่ไปที่อีเมลของบัญชีครับ ถ้าอีเมลนั้นใช้ไม่ได้แล้ว ติดต่อทีมซัพพอร์ตพร้อมหนังสือยืนยันจากบริษัทครับ</p>', 'ทีมซัพพอร์ต', 1, '', '', NULL, NOW() - INTERVAL 3 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (4, 9, 3, '<p>ได้แล้วค่ะ ขอบคุณมากค่ะ</p>', 'คุณมด', 1, '', '', NULL, NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (5, 9, 4, '<p>รูปจากมือถือรุ่นใหม่มักมีขนาดเกิน 10 MB ครับ ลองย่อรูปก่อนอัปโหลด หรือแจ้งผู้ดูแลเพิ่มขนาดไฟล์ที่อนุญาตในหน้าตั้งค่าโมดูลครับ</p>', 'ทีมซัพพอร์ต', 1, '', '', NULL, NOW() - INTERVAL 2 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (6, 9, 4, '<p>ย่อรูปแล้วอัปโหลดได้ครับ</p>', 'คุณบี', 1, '', '', NULL, NOW() - INTERVAL 1 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (7, 9, 4, '<p>ยินดีครับ ระบบจะย่อรูปและแปลงเป็น WebP ให้อัตโนมัติหลังอัปโหลดครับ</p>', 'ทีมซัพพอร์ต', 1, '', '', NULL, NOW() - INTERVAL 0 DAY - INTERVAL 3 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (8, 9, 5, '<p>ขอบคุณสำหรับข้อเสนอแนะครับ ตอนนี้มีวิดีโอสาธิตแล้วหนึ่งตอนที่หน้าวิดีโอ และกำลังทยอยทำเพิ่มครับ</p>', 'ทีมงาน', 1, '', '', NULL, NOW() - INTERVAL 8 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (9, 9, 6, '<p>รองรับครับ ทั้งคิวอาร์โค้ดพร้อมเพย์และบัตรเครดิตผ่านผู้ให้บริการรับชำระเงินครับ</p>', 'ฝ่ายขาย', 1, '', '', NULL, NOW() - INTERVAL 12 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (10, 9, 6, '<p>เยี่ยมครับ ขอใบเสนอราคาทางอีเมลได้เลยครับ</p>', 'คุณก้อง', 1, '', '', NULL, NOW() - INTERVAL 11 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (11, 9, 7, '<p>ย้ายได้ครับ ทีมงานจะประเมินโครงสร้างข้อมูลเดิมก่อน แล้วแจ้งขั้นตอนและระยะเวลาให้ทราบครับ</p>', 'ทีมซัพพอร์ต', 1, '', '', NULL, NOW() - INTERVAL 17 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (12, 9, 8, '<p>ยินดีครับ ขอบคุณที่ไว้วางใจครับ</p>', 'ทีมซัพพอร์ต', 1, '', '', NULL, NOW() - INTERVAL 1 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_textlink` (`id`, `name`, `type`, `text`, `description`, `url`, `target`, `logo`, `width`, `height`, `published`, `link_order`, `created_at`, `publish_start`, `publish_end`) VALUES (1, 'slideshow', 'image', 'โซลูชันดิจิทัล สำหรับธุรกิจยุคใหม่', 'ออกแบบเว็บไซต์ ระบบงานองค์กร และแอปพลิเคชัน ครบจบในที่เดียว', '{WEBURL}services', '_self', 'textlink-1.webp', 1200, 450, 1, 1, NOW() - INTERVAL 30 DAY, 0, 0);
INSERT INTO `{prefix}_textlink` (`id`, `name`, `type`, `text`, `description`, `url`, `target`, `logo`, `width`, `height`, `published`, `link_order`, `created_at`, `publish_start`, `publish_end`) VALUES (2, 'slideshow', 'image', 'ผลงานที่ลูกค้า ไว้วางใจ', 'กว่า 850 โครงการ ทั้งภาคเอกชน ภาครัฐ และสถานศึกษา', '{WEBURL}portfolio', '_self', 'textlink-2.webp', 1200, 450, 1, 2, NOW() - INTERVAL 30 DAY, 0, 0);
